MAP
  NAME "MRMS_MESH"
  STATUS ON
  SIZE 800 600
  EXTENT -130.0 20.0 -60.0 55.0
  UNITS DD
  IMAGECOLOR 0 0 0

  PROJECTION
    "init=epsg:4326"
  END

  SYMBOLSET "/var/www/mapserver/symbols/symbols.map"

  WEB
    METADATA
      "wms_title"           "MRMS MESH Instantaneous Hail"
      "wms_onlineresource"  "http://209.248.90.253/wms/mrms_mesh"
      "wms_srs"             "EPSG:4326 EPSG:3857 EPSG:900913"
      "wms_enable_request"  "*"
      "wms_encoding"        "UTF-8"
      "wms_allow_getmap_without_styles" "true"
    END
  END

  OUTPUTFORMAT
    NAME "png"
    DRIVER "AGG/PNG"
    MIMETYPE "image/png"
    IMAGEMODE RGBA
    EXTENSION "png"
    TRANSPARENT ON
  END

  LAYER
    NAME "mesh"
    TYPE RASTER
    STATUS ON
    DATA "/var/www/mapserver/cache/mesh_current.tif"

    PROJECTION
      "init=epsg:4326"
    END

    PROCESSING "NODATA=-999"

    # Suppress no-hail fill values (negative)
    CLASS
      NAME "no hail"
      EXPRESSION ([pixel] < 0)
      STYLE
        COLOR 0 0 0
        OPACITY 0
      END
    END
    CLASS
      NAME "0-6mm possible"
      EXPRESSION ([pixel] >= 0 AND [pixel] < 6)
      STYLE
        COLOR 100 220 100
        OPACITY 47
      END
    END
    CLASS
      NAME "6-19mm small"
      EXPRESSION ([pixel] >= 6 AND [pixel] < 19)
      STYLE
        COLOR 255 255 0
        OPACITY 82
      END
    END
    CLASS
      NAME "19-25mm penny sig hail"
      EXPRESSION ([pixel] >= 19 AND [pixel] < 25)
      STYLE
        COLOR 255 165 0
        OPACITY 86
      END
    END
    CLASS
      NAME "25-38mm quarter"
      EXPRESSION ([pixel] >= 25 AND [pixel] < 38)
      STYLE
        COLOR 255 60 0
        OPACITY 86
      END
    END
    CLASS
      NAME "38-50mm golf ball"
      EXPRESSION ([pixel] >= 38 AND [pixel] < 50)
      STYLE
        COLOR 200 0 200
        OPACITY 90
      END
    END
    CLASS
      NAME ">=50mm baseball+"
      EXPRESSION ([pixel] >= 50)
      STYLE
        COLOR 255 255 255
        OPACITY 94
      END
    END

    METADATA
      "wms_title" "MRMS Maximum Estimated Size of Hail"
      "wms_srs"   "EPSG:4326 EPSG:3857"
    END
  END
END
